+fn literalString(t: *Template, w: []Value, i: u16) Value {
+    const slot = &w[header + t.nlocals + t.max_stack + i];
+    if (slot.* == rt.undefined_value) slot.* = rt.string(t.strings[i]);
+    return slot.*;
